SELECT 'SCM_MST_SHEET_MEASURE' AS TBL, T.PROGRAM_ID, T.SHEET_NAME
  FROM SCM_MGR.SCM_MST_SHEET_MEASURE T
 WHERE (PROGRAM_ID = 'SCP0125')
   AND NOT EXISTS (SELECT 1 FROM (SELECT CAST(NULL AS VARCHAR2(4000)) PROGRAM_ID, CAST(NULL AS VARCHAR2(4000)) SHEET_NAME FROM DUAL WHERE 1 = 0) S WHERE NVL(TO_CHAR(T.PROGRAM_ID), '~') = NVL(TO_CHAR(S.PROGRAM_ID), '~') AND NVL(TO_CHAR(T.SHEET_NAME), '~') = NVL(TO_CHAR(S.SHEET_NAME), '~'));
